export declare const KIT_DIALOG_KEYFRAMES_CSS = "\n  @keyframes kitModalSpringIn {\n    from {\n      opacity: 0;\n      transform: translateY(14px) scale(0.96);\n    }\n    to {\n      opacity: 1;\n      transform: translateY(0) scale(1);\n    }\n  }\n\n  @keyframes kitModalSpringOut {\n    from {\n      opacity: 1;\n      transform: translateY(0) scale(1);\n    }\n    to {\n      opacity: 0;\n      transform: translateY(10px) scale(0.96);\n    }\n  }\n\n  @keyframes kitSheetSlideUp {\n    from {\n      opacity: 0;\n      transform: translateY(100%);\n    }\n    to {\n      opacity: 1;\n      transform: translateY(0);\n    }\n  }\n\n  @keyframes kitSheetSlideDown {\n    to {\n      opacity: 0;\n      transform: translateY(100%);\n    }\n  }\n\n  @keyframes kitBackdropFadeIn {\n    from {\n      opacity: 0;\n    }\n    to {\n      opacity: 1;\n    }\n  }\n\n  @keyframes kitBackdropFadeOut {\n    from {\n      opacity: 1;\n    }\n    to {\n      opacity: 0;\n    }\n  }\n\n  @keyframes kitSubviewSlideIn {\n    from {\n      opacity: 0;\n      transform: translateX(18px);\n    }\n    to {\n      opacity: 1;\n      transform: translateX(0);\n    }\n  }\n\n  @keyframes kitSubviewSlideBack {\n    from {\n      opacity: 0;\n      transform: translateX(-18px);\n    }\n    to {\n      opacity: 1;\n      transform: translateX(0);\n    }\n  }\n";
